def transform_v4(grid):
    bg, sp = 8, 6
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]
    changed = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                continue

            # Has special on left or right (or both)
            has_any_horizontal = any(grid[r][k] == sp for k in range(w) if k != c)
            # Has special on top or bottom (or both) 
            has_any_vertical = any(grid[k][c] == sp for k in range(h) if k != r)

            # OR rule: between on at least one dimension
            if has_any_horizontal or has_any_vertical:
                changed.add((r, c))

    for r in range(h):
        for c in range(w):
            if (r, c) in changed:
                result[r][c] = 3

    return result

