def apply_rule1(grid):
    """Rule: row_or_col_between (has special on both sides in at least one axis)"""
    bg = grid[0][0]
    sp_set = set()
    for r in grid:
        for val in r:
            if val != bg:
                sp_set.add(val)
    if not sp_set:
        return set()
    sp = sp_set.pop()

    h, w = len(grid), len(grid[0])
    changed = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                continue

            # Row between
            left = any(grid[r][j] == sp for j in range(c))
            right = any(grid[r][j] == sp for j in range(c + 1, w))
            if left and right:
                changed.add((r, c))
                continue  # No need to check column if row is true

            # Col between
            top = any(grid[i][c] == sp for i in range(r))
            bottom = any(grid[i][c] == sp for i in range(r + 1, h))
            if top and bottom:
                changed.add((r, c))

    return changed

